/**
 * nexus-agents scaffold templates
 *
 * Template generators for each scaffold type. Each generator returns
 * an array of files with their paths and content.
 *
 * @module cli/scaffold-templates
 * (Source: Issue #653 - Scaffold command)
 */

import { toPascalCase, toCamelCase, toScreamingSnake } from './scaffold.js';

/** A file to be generated by scaffolding. */
export interface GeneratedFile {
  readonly path: string;
  readonly content: string;
}

/** Generates the imports and schema section of a tool file. */
function toolImportsAndSchema(name: string, pascal: string): string {
  return `/**
 * nexus-agents/mcp - ${pascal} Tool
 *
 * MCP tool for ${name} operations.
 *
 * @module mcp/tools/${name}
 * (Source: Issue #653 - Scaffolded)
 */

import { z } from 'zod';
import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import type { ILogger } from '../../core/index.js';
import { createLogger, formatZodError } from '../../core/index.js';
import type { RateLimiter } from '../middleware/rate-limiter.js';
import type { SecurityConfig } from '../../config/schemas.js';
import { wrapToolWithTimeout, toSdkCallback } from '../middleware/tool-wrapper.js';
import { createSecureHandler, type HandlerContext } from '../middleware/secure-handler.js';

/**
 * Input schema for ${name} tool.
 */
export const ${pascal}InputSchema = z.object({
  // TODO: Define input parameters
  input: z.string().min(1).describe('Input for ${name}'),
});

export type ${pascal}Input = z.infer<typeof ${pascal}InputSchema>;

/**
 * Dependencies for ${name} tool.
 */
export interface ${pascal}Deps {
  logger?: ILogger;
  rateLimiter: RateLimiter;
  security?: SecurityConfig | undefined;
}
`;
}

/** Generates the handler and registration section of a tool file. */
function toolHandlerAndRegistration(name: string, pascal: string): string {
  return `
/**
 * Handles the ${name} tool execution.
 */
function create${pascal}Handler(deps: ${pascal}Deps) {
  return async (args: unknown, ctx: HandlerContext) => {
    const validated = ${pascal}InputSchema.safeParse(args);
    if (!validated.success) {
      return {
        isError: true,
        content: [{ type: 'text' as const, text: \`Validation error: \${formatZodError(validated.error)}\` }],
      };
    }

    ctx.logger.debug('Executing ${name}', { input: validated.data.input });

    // TODO: Implement tool logic
    return {
      content: [{ type: 'text' as const, text: JSON.stringify({ status: 'ok' }, null, 2) }],
    };
  };
}

/**
 * Registers the ${name} tool with the MCP server.
 */
export function register${pascal}Tool(server: McpServer, deps: ${pascal}Deps): void {
  const logger = deps.logger ?? createLogger({ tool: '${name}' });
  const toolSchema = {
    input: z.string().min(1).describe('Input for ${name}'),
  };

  const description = '${pascal} tool - TODO: add description';

  const secureHandler = createSecureHandler(create${pascal}Handler(deps), {
    toolName: '${name}',
    rateLimiter: deps.rateLimiter,
    logger,
  });

  const timeoutMs = deps.security?.timeout?.defaultTimeoutMs;
  const wrappedHandler = wrapToolWithTimeout(
    '${name}',
    secureHandler,
    timeoutMs !== undefined ? { timeoutMs, logger } : { logger }
  );

  server.registerTool(
    '${name}',
    { description, inputSchema: toolSchema },
    toSdkCallback(wrappedHandler)
  );
  logger.info('Registered ${name} tool');
}
`;
}

/** Generates MCP tool source file content. */
function toolSourceContent(name: string, pascal: string): string {
  return toolImportsAndSchema(name, pascal) + toolHandlerAndRegistration(name, pascal);
}

/** Generates MCP tool test file content. */
function toolTestContent(name: string, pascal: string): string {
  return `/**
 * Tests for ${name} tool.
 * (Source: Issue #653 - Scaffolded)
 */

import { describe, it, expect } from 'vitest';
import { ${pascal}InputSchema } from './${name}.js';

describe('${pascal} Tool', () => {
  describe('${pascal}InputSchema', () => {
    it('should validate valid input', () => {
      const result = ${pascal}InputSchema.safeParse({ input: 'test' });
      expect(result.success).toBe(true);
    });

    it('should reject empty input', () => {
      const result = ${pascal}InputSchema.safeParse({ input: '' });
      expect(result.success).toBe(false);
    });
  });
});
`;
}

/** Generates MCP tool files (source + test). */
export function generateToolFiles(name: string): GeneratedFile[] {
  const pascal = toPascalCase(name);
  return [
    { path: `src/mcp/tools/${name}.ts`, content: toolSourceContent(name, pascal) },
    { path: `src/mcp/tools/${name}.test.ts`, content: toolTestContent(name, pascal) },
  ];
}

