/** Generates CLI command source file content. */
function commandSourceContent(name: string, pascal: string, camel: string): string {
  return `/**
 * nexus-agents ${name} command
 *
 * TODO: Add command description.
 *
 * @module cli/${name}
 * (Source: Issue #653 - Scaffolded)
 */

export interface ${pascal}Options {
  readonly verbose?: boolean;
}

export interface ${pascal}Result {
  readonly success: boolean;
  readonly message: string;
}

/**
 * Runs the ${name} command logic.
 */
export function run${pascal}(options: ${pascal}Options): ${pascal}Result {
  // TODO: Implement command logic
  void options;
  return { success: true, message: '${pascal} completed' };
}

/**
 * Prints the ${name} result to stdout.
 */
export function print${pascal}Result(result: ${pascal}Result): void {
  process.stdout.write(result.message + '\\n');
}

/**
 * Main command entry point. Returns exit code.
 */
export function ${camel}Command(options: ${pascal}Options): number {
  const result = run${pascal}(options);
  print${pascal}Result(result);
  return result.success ? 0 : 1;
}
`;
}

/** Generates CLI command test file content. */
function commandTestContent(name: string, pascal: string, camel: string): string {
  return `/**
 * Tests for ${name} command.
 * (Source: Issue #653 - Scaffolded)
 */

import { describe, it, expect, vi } from 'vitest';
import { run${pascal}, ${camel}Command } from './${name}.js';

describe('${pascal} Command', () => {
  describe('run${pascal}()', () => {
    it('should return success', () => {
      const result = run${pascal}({});
      expect(result.success).toBe(true);
    });
  });

  describe('${camel}Command()', () => {
    it('should return 0 for success', () => {
      vi.spyOn(process.stdout, 'write').mockImplementation(() => true);
      const exitCode = ${camel}Command({});
      expect(exitCode).toBe(0);
    });
  });
});
`;
}

/** Generates CLI command files (source + test). */
export function generateCommandFiles(name: string): GeneratedFile[] {
  const pascal = toPascalCase(name);
  const camel = toCamelCase(name);
  return [
    { path: `src/cli/${name}.ts`, content: commandSourceContent(name, pascal, camel) },
    { path: `src/cli/${name}.test.ts`, content: commandTestContent(name, pascal, camel) },
  ];
}
